import{z as d,x as p,o,c as A,q as l,j as s,D as e,d as r,s as n,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"协程与生成器实现","description":"","frontmatter":{"title":"协程与生成器实现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/coroutines-impl.md","filePath":"cs/coroutines-impl.md","lastUpdated":1791413859000}'),B={name:"cs/coroutines-impl.md"};function c(m,a,u,h,C,D){const i=p("Mermaid");return o(),A("div",null,[a[2]||(a[2]=l('<h1 id="协程与生成器实现" tabindex="-1">协程与生成器实现 <a class="header-anchor" href="#协程与生成器实现" aria-label="Permalink to &quot;协程与生成器实现&quot;">​</a></h1><div class="epigraph"><p>生成器是半协程：`yield` 保存 PC 与局部，下次从该点继续。实现或把状态机编到堆帧，或切换独立栈。</p><footer>—— 据 Moura and Ierusalimschy, Revisiting Coroutines；C# / Python 生成器实现；对照 CPS 整理</footer></div><p>上一课<a href="/cs/cps-continuations">CPS</a> 把控制变成函数。生成器不必全 CPS：编译器把函数切成状态机。缺口是<strong>暂停点的帧</strong>。蹦床下一课。不写异步 IO 框架百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>yield x</code> 返回值给调用者，但局部还要活。方案 A：变换成类，字段=局部，<code>switch(state)</code>。方案 B：独立栈，切换 SP。缺口是<strong>与 GC 根、展开表的关系</strong>，不是 call/cc 全权。</p><p>async/await 是生成器+将来值的语法，实现同类。</p><h3 id="生成器不是操作系统线程" tabindex="-1">生成器不是操作系统线程 <a class="header-anchor" href="#生成器不是操作系统线程" aria-label="Permalink to &quot;生成器不是操作系统线程&quot;">​</a></h3><p>用户态、协作式。不要和抢占线程混。切换代价应远小于 <code>pthread</code>。</p><p><span class="marginnote">Moura–Ierusalimschy。Python 的 frame 对象。LLVM 协程表示（CoroSplit）。本课两种实现对照。</span></p><p><span class="marginnote">PC（程序计数器）翻译过来就是「下一条执行哪条指令」的游标。yield 的本质是把游标连同局部变量打包存进协程帧：函数并没有真正结束，下次 resume 把游标拨回暂停处，从半句话中间接着讲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端标暂停点。CoroSplit：把 SSA 跨 yield 的值溢到协程帧。调用：resume 恢复 PC。完成：销毁帧。</p>',12)),(o(),s(E,null,{default:e(()=>[n(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20YLD%5B%22yield%22%5D%20--%3E%20SAVE%5B%22%E4%BF%9D%E5%AD%98%20PC%20%E4%B8%8E%E6%B4%BB%E5%80%BC%22%5D%0A%20%20SAVE%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E8%B0%83%E7%94%A8%E8%80%85%22%5D%0A%20%20RET%20--%3E%20RES%5B%22resume%20%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与闭包：协程帧是环境的亲戚。与 DWARF：展开要认协程帧布局。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"栈满协程：每个协程一页栈，内存多。状态机：内存少，不能任意深度互递归 yield 除非堆分配。不要在持锁时 yield 而不文档。",-1)),(o(),s(E,null,{default:e(()=>[n(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E9%80%89%E5%8D%8F%E7%A8%8B%E5%AE%9E%E7%8E%B0%22%5D%20--%3E%20SM%5B%22%E6%97%A0%E6%A0%88%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20CH%20--%3E%20SF%5B%22%E6%9C%89%E6%A0%88%E5%8D%8F%E7%A8%8B%22%5D%0A%20%20SM%20--%3E%20SMI%5B%22%E5%8F%AA%E5%AD%98%E5%8D%8F%E7%A8%8B%E5%B8%A7%20%E6%9E%81%E7%9C%81%E5%86%85%E5%AD%98%20%C2%B7%20%E4%B8%8D%E8%83%BD%E6%B7%B1%E5%B1%82%E4%BA%92%20yield%22%5D%0A%20%20SF%20--%3E%20SFI%5B%22%E7%8B%AC%E7%AB%8B%E6%A0%88%E5%8F%AF%E4%BB%BB%E6%84%8F%E5%B5%8C%E5%A5%97%20%C2%B7%20%E6%AF%8F%E4%B8%AA%E5%8D%8F%E7%A8%8B%E7%BA%A6%E4%B8%80%E9%A1%B5%E5%86%85%E5%AD%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">直觉类比：栈满协程像给每个任务一间独立办公室，随时走人随时回来，东西都留在桌上；状态机像让员工把进度填进一张表格再走，回来照表继续——便宜得多，但表上没登记的东西就丢了，所以编译器必须精确算出哪些活值要溢进协程帧。</span></p><p>异常：在 yield 对面抛，状态机要能传播。</p><p><span class="marginnote">常见误区：以为协程切换像函数调用一样免费且无副作用。实际上 yield 点是「世界可能变了」的时刻——你持有的锁、正在遍历的容器都可能被对面协程动过；持锁 yield 引发的死锁没有时钟中断来解围，全靠自己约定避免。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写蹦床。后课默认：生成器=可暂停帧。下一课蹦床与尾递归：另一套无栈控制。</p><p>也不把协程当化学课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生成器：状态机或独立栈保存暂停点。</li><li>与 CPS 同类控制，实现更特化。</li><li>GC、展开、锁是正确性边界。</li><li>出处：Moura and Ierusalimschy；语言实现（Python/C#）；LLVM CoroSplit。</li></ul>',8))])}const P=d(B,[["render",c]]);export{f as __pageData,P as default};
